import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x89958a);scene.fog=new THREE.FogExp2(0x89958a,.018);
const camera=new THREE.PerspectiveCamera(72,innerWidth/innerHeight,.08,120);camera.position.set(0,1.68,8);camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;mount.appendChild(renderer.domElement);
const hemi=new THREE.HemisphereLight(0xdce9d3,0x353c35,2.1);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffe6bd,3.2);sun.position.set(-8,15,6);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-22;sun.shadow.camera.right=22;sun.shadow.camera.top=22;sun.shadow.camera.bottom=-22;scene.add(sun);
const fill=new THREE.PointLight(0x9ab8b0,35,28);fill.position.set(4,5,-7);scene.add(fill);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const concrete=mat(0x73796e),wallMat=mat(0x515b53),floorMat=mat(0x596257),crateMat=mat(0x9a805d),crateDark=mat(0x695a44),metal=mat(0x353d3c,.42,.7),dark=mat(0x171d1c,.5,.5),lime=mat(0xc9f45a,.4,.25),enemyMat=mat(0x9c5145),cloth=mat(0x48534b),skin=mat(0xc99d78),glass=mat(0x6e9087,.25,.5);
const boxGeo=new THREE.BoxGeometry(1,1,1);
function cube(parent,x,y,z,sx,sy,sz,material,shadow=true){const m=new THREE.Mesh(boxGeo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=shadow;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,r1,r2,h,material,x,y,z,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
// Ground and enclosed industrial courtyard
const floor=new THREE.Mesh(new THREE.PlaneGeometry(42,42),floorMat);floor.rotation.x=-Math.PI/2;floor.position.y=-.03;floor.receiveShadow=true;scene.add(floor);
// subtle floor lane markings
const paint=mat(0xb5b18a,.9,0);for(let z=-15;z<17;z+=5){const stripe=cube(scene,0,.005,z,10,.012,.035,paint,false);stripe.material=paint}
// Outer barriers and blocky architecture
cube(scene,0,2,-20,42,4,1,wallMat);cube(scene,-21,2,0,1,4,40,wallMat);cube(scene,21,2,0,1,4,40,wallMat);cube(scene,0,2,20,42,4,1,wallMat);
// Tall back building and entry frame
cube(scene,-7,4,-17,13,8,2,concrete);cube(scene,-7,8,-17.1,14,.35,2.4,metal);cube(scene,-7,1.5,-15.9,5,3,1.4,dark);cube(scene,-7,3.3,-15.12,3,.12,.08,lime,false);
cube(scene,12,2,-15,12,4,2,wallMat);cube(scene,12,4.1,-15,13,.25,2.3,metal);
// Pillars, cover and site containers
const covers=[[-9,-7,3.6,2.4,3.1],[-3,-7,2.5,2.4,2.4],[6,-8,3.3,2.6,3],[10,-4,2.6,2.2,2.5],[-10,1,3.2,2.2,2.5],[-4,3,2.7,2.2,2.2],[4,2,3.5,2.2,2.7],[10,5,2.5,2.4,2.4],[-8,10,3.2,2.6,2.8],[1,11,2.7,2.4,2.2],[9,12,3.3,2.5,2.8]];
for(const [x,z,w,d,h] of covers){cube(scene,x,h/2,z,w,h,d,crateMat);for(let yy=.28;yy<h;yy+=.55){cube(scene,x,yy,z-d/2-.012,w*.88,.045,.03,crateDark,false)}cube(scene,x,Math.min(h-.25,1),z-d/2-.035,w*.22,.12,.04,lime,false);cube(scene,x,Math.min(h-.3,1.5),z+d/2+.03,w*.7,.05,.04,metal,false)}
// Site marking
const site=new THREE.Mesh(new THREE.RingGeometry(3.2,3.3,48),new THREE.MeshBasicMaterial({color:0xc9f45a,transparent:true,opacity:.65,side:THREE.DoubleSide}));site.rotation.x=-Math.PI/2;site.position.set(0,.02,-8);scene.add(site);
for(let i=0;i<4;i++){const p=new THREE.PointLight(0xc9f45a,2.2,5);const a=i*Math.PI/2;p.position.set(Math.cos(a)*3.25,.18,-8+Math.sin(a)*3.25);scene.add(p)}
// Industrial lamps and aerials
for(const x of [-16,16]){cylinder(scene,.1,.13,7,metal,x,3.5,-11);const bulb=new THREE.Mesh(new THREE.SphereGeometry(.22,12,8),new THREE.MeshBasicMaterial({color:0xffd49a}));bulb.position.set(x,7,-11);scene.add(bulb);const spot=new THREE.SpotLight(0xffd4a0,24,18,.62,.65,1.6);spot.position.set(x,6.8,-11);spot.target.position.set(x,0,-6);scene.add(spot,spot.target)}
// Air particles / drifting dust
const dustGeo=new THREE.BufferGeometry(),dustCount=160,dustPositions=new Float32Array(dustCount*3);for(let i=0;i<dustCount;i++){dustPositions[i*3]=(Math.random()-.5)*36;dustPositions[i*3+1]=Math.random()*5+.3;dustPositions[i*3+2]=(Math.random()-.5)*36}dustGeo.setAttribute('position',new THREE.BufferAttribute(dustPositions,3));scene.add(new THREE.Points(dustGeo,new THREE.PointsMaterial({color:0xd9d3b4,size:.035,transparent:true,opacity:.44})));
// First person weapon: procedural, articulated sci-fi assault rifle
const gun=new THREE.Group();camera.add(gun);scene.add(camera);gun.position.set(.35,-.3,-.56);gun.rotation.set(-.02,-.04,0);
function gunBox(x,y,z,sx,sy,sz,material){return cube(gun,x,y,z,sx,sy,sz,material,false)}
gunBox(0,0,0,.16,.17,.57,dark);gunBox(0,.04,-.11,.22,.11,.39,metal);gunBox(0,.1,-.12,.14,.08,.28,cloth);gunBox(0,.005,-.38,.1,.095,.43,metal);cylinder(gun,.028,.028,.46,dark,0,.012,-.74,10).rotation.x=Math.PI/2;
gunBox(0,.14,-.12,.075,.05,.16,dark);gunBox(.002,.17,-.12,.025,.02,.1,lime);gunBox(0,-.16,-.16,.11,.25,.16,cloth);gunBox(0,-.09,-.42,.09,.16,.12,dark);gunBox(-.13,-.005,-.12,.09,.11,.3,metal);gunBox(.13,-.005,-.12,.09,.11,.3,metal);
// Sight rings
const sight=new THREE.Mesh(new THREE.TorusGeometry(.045,.009,6,12),lime);sight.position.set(0,.23,-.14);gun.add(sight);sight.rotation.x=Math.PI/2;
// Arms / gloves visible under rifle
const armMat=mat(0x3c4740),gloveMat=mat(0x222826,.8,.1);const leftArm=cube(gun,-.22,-.15,-.26,.12,.12,.38,armMat);leftArm.rotation.x=-.25;const rightArm=cube(gun,.18,-.21,.02,.13,.14,.28,armMat);rightArm.rotation.z=-.18;
const hands=cube(gun,.02,-.13,-.29,.19,.09,.15,gloveMat);
// Bot character factory
const enemies=[];const enemyPositions=[[-13,-11],[1,-13],[15,-8],[-1,-1]];
function makeBot(x,z,index){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const body=new THREE.Group();g.add(body);
 const torso=cylinder(body,.27,.31,.72,enemyMat,0,1.12,0,10);torso.rotation.z=Math.PI/2; // replaced orientation below with torso box
 body.remove(torso);cube(body,0,1.25,0,.55,.72,.34,enemyMat);cube(body,0,1.59,0,.6,.16,.36,metal);cube(body,0,1.07,-.19,.25,.26,.08,cloth);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.19,12,10),skin);head.position.set(0,1.83,0);head.castShadow=true;body.add(head);
 const helmet=new THREE.Mesh(new THREE.SphereGeometry(.22,12,8,0,Math.PI*2,0,Math.PI*.52),dark);helmet.position.set(0,1.88,0);helmet.castShadow=true;body.add(helmet);cube(body,0,1.8,-.18,.42,.08,.08,metal);
 const mask=cube(body,0,1.77,-.195,.25,.12,.04,cloth);cube(body,0,1.78,-.221,.1,.035,.02,lime,false);
 const limbs=[];for(const side of [-1,1]){const arm=new THREE.Group();arm.position.set(side*.36,1.42,0);body.add(arm);cube(arm,0,-.28,0,.16,.53,.17,cloth);cube(arm,0,-.51,-.07,.15,.13,.12,gloveMat);limbs.push(arm);
 const leg=new THREE.Group();leg.position.set(side*.16,.82,0);body.add(leg);cube(leg,0,-.38,0,.2,.77,.23,dark);cube(leg,0,-.75,-.08,.24,.14,.38,metal);limbs.push(leg)}
 // weapon across chest, aimed outward
 const rifle=new THREE.Group();rifle.position.set(.12,1.23,-.25);rifle.rotation.x=-.12;body.add(rifle);cube(rifle,0,0,0,.11,.13,.48,dark);cube(rifle,0,.02,-.32,.055,.06,.35,metal);cube(rifle,0,-.12,-.07,.1,.22,.1,cloth);cylinder(rifle,.02,.02,.24,metal,0,.02,-.54,8).rotation.x=Math.PI/2;
 // glowing hostile shoulder patch and eye lights
 const patch=cube(body,-.29,1.49,-.18,.06,.13,.03,lime,false);
 const enemy={group:g,body,limbs,x,z,hp:100,alive:true,cooldown:1.4+Math.random()*1.5,phase:Math.random()*6,walk:0,index,patch};enemies.push(enemy);return enemy}
enemyPositions.forEach((p,i)=>makeBot(...p,i));
// Runtime state
const state={active:false,paused:false,ended:false,hp:100,armor:100,ammo:30,reserve:90,reloading:false,weapon:0,score:0,elapsed:0,walk:0,fireCooldown:0,mouseDown:false};
let yaw=0,pitch=0;const keys={};const clock=new THREE.Clock();const raycaster=new THREE.Raycaster();raycaster.far=70;const center=new THREE.Vector2(0,0);
const menu=document.querySelector('#menu'),pauseCard=document.querySelector('#pause'),mobile=document.querySelector('#mobile');const toast=document.querySelector('#toast');let toastTimer;
function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),1250)}
function startGame(){if(state.ended)resetGame();state.active=true;state.paused=false;menu.classList.add('hidden');pauseCard.classList.remove('show');mobile.classList.add('active');if(innerWidth>700)renderer.domElement.requestPointerLock?.();}
function pauseGame(){if(!state.active)return;state.paused=!state.paused;pauseCard.classList.toggle('show',state.paused);if(state.paused&&document.pointerLockElement)document.exitPointerLock();else if(!state.paused&&innerWidth>700)renderer.domElement.requestPointerLock?.()}
document.querySelector('#playBtn').onclick=startGame;document.querySelector('#pauseBtn').onclick=pauseGame;document.querySelector('#resumeBtn').onclick=()=>{state.paused=false;pauseCard.classList.remove('show');if(innerWidth>700)renderer.domElement.requestPointerLock?.()};
document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&state.active&&!state.paused&&innerWidth>700)pauseGame()});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement&&state.active){yaw-=e.movementX*.0022;pitch-=e.movementY*.0022;pitch=THREE.MathUtils.clamp(pitch,-1.25,1.25)}});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='Escape'&&state.active)pauseGame();if(e.code==='KeyR')reload();if(e.code==='Digit1')setWeapon(0);if(e.code==='Digit2')setWeapon(1)});document.addEventListener('keyup',e=>keys[e.code]=false);
document.addEventListener('mousedown',e=>{if(e.button===0){state.mouseDown=true;if(state.active&&!state.paused)shoot()}});document.addEventListener('mouseup',e=>{if(e.button===0)state.mouseDown=false});
function setWeapon(which){state.weapon=which;document.querySelector('#weaponName').textContent=which?'M7 COMPACT':'VX-9 VANDAL';document.querySelector('#weaponType').textContent=which?'SIDEARM · 9 MM':'ASSAULT RIFLE · 5.56 MM';document.querySelector('#weaponIcon').textContent=which?'⌖':'⌁';state.ammo=which?12:30;state.reserve=which?36:90;updateAmmo();}
function updateAmmo(){document.querySelector('#ammo').innerHTML=`${state.reloading?'—':state.ammo} <span>/ ${state.reserve}</span>`}
function reload(){if(!state.active||state.paused||state.reloading||state.ammo===(state.weapon?12:30)||state.reserve<=0)return;state.reloading=true;notify('ПЕРЕЗАРЯДКА');gun.userData.reloadStart=performance.now();setTimeout(()=>{if(!state.active)return;const cap=state.weapon?12:30;const n=Math.min(cap-state.ammo,state.reserve);state.ammo+=n;state.reserve-=n;state.reloading=false;gun.userData.reloadStart=0;updateAmmo()},state.weapon?1050:1450);updateAmmo()}
function shoot(){if(!state.active||state.paused||state.reloading||state.fireCooldown>0)return;if(state.ammo<=0){notify('НЕТ ПАТРОНОВ — R ДЛЯ ПЕРЕЗАРЯДКИ');state.fireCooldown=.3;return}state.fireCooldown=state.weapon?.27:.115;state.ammo--;updateAmmo();gun.userData.recoil=.11;gun.userData.flash=.07;
 camera.updateMatrixWorld();raycaster.setFromCamera(center,camera);const objects=[];for(const e of enemies)if(e.alive){e.body.traverse(o=>{if(o.isMesh)objects.push(o)})}const hit=raycaster.intersectObjects(objects,false)[0];if(hit){const e=enemies.find(v=>v.alive&&v.body===hit.object.parent);let target=e;if(!target)target=enemies.find(v=>v.alive&&v.body.children.includes(hit.object));if(!target){target=enemies.find(v=>v.alive&&v.body.getObjectById(hit.object.parent?.id))}if(!target){let o=hit.object;while(o&& !enemies.some(v=>v.body===o))o=o.parent;target=enemies.find(v=>v.body===o)}if(target){target.hp-=state.weapon?42:34;hit.object.material=hit.object.material;target.hitFlash=.13;if(target.hp<=0)killBot(target)}}
}
function killBot(e){e.alive=false;e.group.rotation.z=.0;e.group.position.y=-.03;state.score++;document.querySelector('#remaining').textContent=Math.max(0,enemies.filter(q=>q.alive).length);document.querySelector('#score').textContent=`${String(Math.min(9,2+Math.floor(state.score/3))).padStart(2,'0')} — 01`;const feed=document.querySelector('#killfeed'),row=document.createElement('div');row.className='kill';row.innerHTML='<b>VANGUARD</b> ✦ '+['SCOUT','RANGER','WARDEN','SENTINEL'][e.index%4];feed.prepend(row);setTimeout(()=>row.remove(),4000);if(!enemies.some(v=>v.alive)){state.ended=true;state.active=false;document.exitPointerLock?.();menu.classList.remove('hidden');document.querySelector('.eyebrow').textContent='СЕКТОР ЗАЧИЩЕН · ОТЛИЧНАЯ РАБОТА';document.querySelector('.title').innerHTML='MISSION<br><span>COMPLETE</span>';document.querySelector('.subtitle').textContent=`Все угрозы устранены. Точность и решительность — залог успеха. Устранено противников: ${state.score}.`;document.querySelector('#playBtn').innerHTML='ПОВТОРИТЬ ОПЕРАЦИЮ <span>↗</span>';}}
function resetGame(){state.ended=false;state.hp=100;state.armor=100;state.ammo=state.weapon?12:30;state.reserve=state.weapon?36:90;state.score=0;state.elapsed=0;camera.position.set(0,1.68,8);yaw=0;pitch=0;for(const e of enemies){e.hp=100;e.alive=true;e.group.position.set(enemyPositions[e.index][0],0,enemyPositions[e.index][1]);e.group.rotation.set(0,0,0);e.cooldown=1+Math.random()*1.5}document.querySelector('#remaining').textContent='4';document.querySelector('#score').textContent='02 — 01';document.querySelector('.eyebrow').textContent='ОРБИТАЛЬНЫЙ КОМПЛЕКС · 2049';document.querySelector('.title').innerHTML='LAST<br><span>LIGHT</span>';document.querySelector('.subtitle').textContent='Группа противника захватила передовой узел связи. Зачисти сектор и удержи позицию до эвакуации.';document.querySelector('#playBtn').innerHTML='НАЧАТЬ ОПЕРАЦИЮ <span>↗</span>';updateAmmo()}
function playerDamage(amount){if(state.armor>0){const absorbed=Math.min(state.armor,amount*.65);state.armor-=absorbed;amount-=absorbed}state.hp=Math.max(0,state.hp-amount);document.querySelector('#health').textContent=Math.ceil(state.hp);document.querySelector('#armor').textContent=Math.ceil(state.armor);document.querySelector('#healthbar').style.width=state.hp+'%';document.querySelector('#armorbar').style.width=state.armor+'%';const flash=document.querySelector('#damageflash');flash.classList.add('on');setTimeout(()=>flash.classList.remove('on'),120);if(state.hp<=0){state.active=false;state.ended=true;document.exitPointerLock?.();menu.classList.remove('hidden');document.querySelector('.eyebrow').textContent='СИГНАЛ ПОТЕРЯН';document.querySelector('.title').innerHTML='MISSION<br><span>FAILED</span>';document.querySelector('.subtitle').textContent='Оператор выведен из строя. Соберись и попробуй снова.';document.querySelector('#playBtn').innerHTML='ПОВТОРИТЬ ОПЕРАЦИЮ <span>↗</span>'}}
// Touch joystick + look swipes and fire button
let joyPointer=null,joyStart={x:0,y:0};const joy=document.querySelector('#joy');joy.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joyStart={x:e.clientX,y:e.clientY};joy.setPointerCapture(e.pointerId)});joy.addEventListener('pointermove',e=>{if(e.pointerId!==joyPointer)return;const dx=e.clientX-joyStart.x,dy=e.clientY-joyStart.y;keys.KeyW=dy<-12;keys.KeyS=dy>12;keys.KeyA=dx<-12;keys.KeyD=dx>12;joy.querySelector('i').style.transform=`translate(${THREE.MathUtils.clamp(dx,-28,28)}px,${THREE.MathUtils.clamp(dy,-28,28)}px)`});function endJoy(){joyPointer=null;keys.KeyW=keys.KeyA=keys.KeyS=keys.KeyD=false;joy.querySelector('i').style.transform=''}joy.addEventListener('pointerup',endJoy);joy.addEventListener('pointercancel',endJoy);
let lookPointer=null,lastTouch={x:0,y:0};renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&e.clientX>innerWidth*.45){lookPointer=e.pointerId;lastTouch={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId)}});renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerId===lookPointer){yaw-=(e.clientX-lastTouch.x)*.006;pitch=THREE.MathUtils.clamp(pitch-(e.clientY-lastTouch.y)*.006,-1.2,1.2);lastTouch={x:e.clientX,y:e.clientY}}});renderer.domElement.addEventListener('pointerup',e=>{if(e.pointerId===lookPointer)lookPointer=null});document.querySelector('#fireBtn').addEventListener('pointerdown',e=>{e.preventDefault();shoot();state.mouseDown=true});document.querySelector('#fireBtn').addEventListener('pointerup',()=>state.mouseDown=false);document.querySelector('#reloadBtn').onclick=reload;
function updateBots(dt,t){for(const e of enemies){if(!e.alive)continue;e.phase+=dt;const dx=camera.position.x-e.group.position.x,dz=camera.position.z-e.group.position.z,dist=Math.hypot(dx,dz);e.group.rotation.y=Math.atan2(dx,dz);e.walk+=dt*(dist>6?5:1);e.limbs[0].rotation.x=Math.sin(e.walk)*.36;e.limbs[2].rotation.x=-Math.sin(e.walk)*.36;e.limbs[1].rotation.x=-.12+Math.sin(e.walk)*.22;e.limbs[3].rotation.x=-Math.sin(e.walk)*.22;
 if(dist>5.2&&dist<22){const pace=.48*dt;e.group.position.x+=dx/dist*pace;e.group.position.z+=dz/dist*pace}e.cooldown-=dt;if(dist<20&&e.cooldown<=0){e.cooldown=1.5+Math.random()*1.4;if(Math.random()<Math.max(.16,.54-dist*.012))playerDamage(4+Math.random()*5)}if(e.hitFlash>0){e.hitFlash-=dt;e.body.traverse(o=>{if(o.isMesh&&o.material===enemyMat)o.material.emissive.setHex(0x772211)})}else enemyMat.emissive.setHex(0x000000);e.group.position.y=Math.sin(e.phase*2)*.018}}
function movePlayer(dt){if(!state.active||state.paused)return;let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);const len=Math.hypot(forward,side)||1;forward/=len;side/=len;const speed=(keys.ShiftLeft||keys.ShiftRight?7.4:4.7)*dt;const dx=-Math.sin(yaw)*forward+Math.cos(yaw)*side,dz=-Math.cos(yaw)*forward-Math.sin(yaw)*side;const nx=THREE.MathUtils.clamp(camera.position.x+dx*speed,-18.5,18.5),nz=THREE.MathUtils.clamp(camera.position.z+dz*speed,-18.5,18.5);
 function blocked(x,z){for(const [cx,cz,w,d,h] of covers)if(Math.abs(x-cx)<w*.5+.32&&Math.abs(z-cz)<d*.5+.32)return true;return false}if(!blocked(nx,camera.position.z))camera.position.x=nx;if(!blocked(camera.position.x,nz))camera.position.z=nz;state.walk+=(Math.abs(forward)+Math.abs(side))*dt*9;camera.position.y=1.68+Math.sin(state.walk)*.025*(forward||side?1:0);camera.rotation.set(pitch,yaw,0,'YXZ');}
function updateHud(t,dt){if(state.active&&!state.paused){state.elapsed+=dt;const total=Math.max(0,105-state.elapsed),mm=String(Math.floor(total/60)).padStart(2,'0'),ss=String(Math.floor(total%60)).padStart(2,'0');document.querySelector('#clock').textContent=`${mm}:${ss}`;if(total===0){notify('ВРЕМЯ ВЫШЛО');state.elapsed=0}}const dots=document.querySelector('#mapdots');dots.innerHTML='';for(const e of enemies)if(e.alive){const d=document.createElement('i');d.className='m-dot enemy';d.style.left=`${50+e.group.position.x*2.7}%`;d.style.top=`${53+e.group.position.z*2.7}%`;dots.appendChild(d)}const mp=document.querySelector('#mapplayer');mp.style.left=`${50+camera.position.x*2.7}%`;mp.style.top=`${53+camera.position.z*2.7}%`;mp.style.transform=`translate(-50%,-50%) rotate(${yaw*180/Math.PI}deg)`;state.fireCooldown=Math.max(0,state.fireCooldown-dt);if(state.mouseDown&&state.active&&!state.paused&&state.weapon===0)shoot();
 const recoil=gun.userData.recoil||0;gun.userData.recoil=Math.max(0,recoil-dt*.42);gun.position.z=-.56+gun.userData.recoil;gun.rotation.x=-.02+gun.userData.recoil*.55;gun.position.y=-.3+Math.sin(state.walk)*.006;const reloadStart=gun.userData.reloadStart;if(reloadStart&&performance.now()-reloadStart<1250){const p=(performance.now()-reloadStart)/1250;gun.rotation.z=Math.sin(p*Math.PI)*.65;gun.position.y=-.3-Math.sin(p*Math.PI)*.12}else gun.rotation.z=0;}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05),t=clock.elapsedTime;if(state.active&&!state.paused){movePlayer(dt);updateBots(dt,t)}updateHud(t,dt);renderer.render(scene,camera)}animate();
